/**
 * A new project in the same workspace. Description, visibility, colour and lead
 * come from the source; status starts active with no dates. Live issues are
 * copied only when `includeIssues` is set, renumbered from 1, reset to the
 * workspace default status, and left unassigned. Comments stay on the source.
 * One `project.cloned` event is published — not `project.created` or
 * `issue.created` — and the search index, usage meters and audit row those
 * events would have driven are written here.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", source.id, source);
  assertCan(actor, "project:read", projectResource(source));
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const projectsUsed = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", projectsUsed)) {
    throw new Error(
      `Plan ${org.plan} allows ${projectsUsed} projects; upgrade to add another`,
    );
  }

  const includeIssues = input.includeIssues ?? true;
  const toCopy = includeIssues
    ? await issueRepo.listLiveIssuesByNumber(input.orgId, source.id)
    : [];

  if (
    toCopy.length > 0 &&
    wouldExceedLimit(org.plan, "issuesPerProject", 0, toCopy.length)
  ) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${input.key}`,
    );
  }

  const project = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug: input.slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  const status = defaultIssueStatus(org.settings.defaultIssueStatus);
  const copies = [];
  for (const issue of toCopy) {
    copies.push(
      await issueRepo.insertIssue(
        {
          orgId: input.orgId,
          projectId: project.id,
          title: issue.title,
          description: issue.description,
          status,
          priority: issue.priority,
          assigneeId: null,
          parentId: null,
          estimate: issue.estimate,
          dueAt: issue.dueAt,
          labelIds: [...issue.labelIds],
        },
        actor.userId,
        copies.length + 1,
      ),
    );
  }

  await indexProject(input.orgId, project);
  for (const issue of copies) {
    await indexIssue(input.orgId, issue);
  }

  await usageRepo.incrementUsage(input.orgId, {
    projectsUsed: 1,
    issuesUsed: copies.length,
  });

  await record(input.orgId, "project.cloned", {
    actorId: actor.userId,
    subjectKind: "project",
    subjectId: project.id,
    projectId: project.id,
    summary: `Cloned project ${project.name}`,
    metadata: {
      sourceProjectId: source.id,
      issuesCopied: copies.length,
    },
  });

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied: copies.length,
  });

  return project;
}

function defaultIssueStatus(value: string): IssueStatus {
  return (ISSUE_STATUSES as readonly string[]).includes(value)
    ? (value as IssueStatus)
    : "backlog";
}

